    expect(run(path, { kind: "list" })).toBe("[ ] b\n[ ] c");
    run(path, { kind: "complete", id: 2 });
    run(path, { kind: "complete", id: 3 });
    expect(run(path, { kind: "clear" })).toBe("Cleared 2 todos");
    expect(run(path, { kind: "list" })).toBe(list([]));
  });
});

